"""Local image demo, bind to loopback only, no public upload."""
import argparse,base64,io,json,pathlib,tempfile
from http.server import BaseHTTPRequestHandler,HTTPServer
from PIL import Image
from common import load_model,predict
PAGE='''<!doctype html><html lang="tr"><meta charset="utf-8"><title>KTU.AI Marathon Demo</title><style>body{font:18px Arial;max-width:800px;margin:40px auto;padding:20px}img{max-width:350px}pre{white-space:pre-wrap}</style><img alt="KTU.AI" style="width:220px;height:auto" src="data:image/png;base64,"><h1>KTU.AI Marathon Görüntü Analizi</h1><p>Eğitim ve araştırma prototipi. Sağlık verilerinde klinik kullanım için uygun değildir.</p><input type="file" id="file" accept="image/png,image/jpeg"><button id="run">Analiz et</button><p id="error"></p><img id="preview"><pre id="result"></pre><script>document.getElementById('run').onclick=async()=>{const f=document.getElementById('file').files[0];if(!f)return;document.getElementById('preview').src=URL.createObjectURL(f);try{const r=await fetch('/predict',{method:'POST',body:f});const data=await r.json();document.getElementById('result').textContent=JSON.stringify(data,null,2);}catch(e){document.getElementById('error').textContent=String(e);}};</script></html>'''
def main():
    p=argparse.ArgumentParser();p.add_argument('--model',required=True);p.add_argument('--port',type=int,default=8000);a=p.parse_args();m=load_model(a.model)
    class Handler(BaseHTTPRequestHandler):
        def do_GET(self):
            if self.path!='/':self.send_error(404);return
            b=PAGE.encode();self.send_response(200);self.send_header('Content-Type','text/html; charset=utf-8');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b)
        def do_POST(self):
            try:
                if self.path!='/predict':raise ValueError('Unknown endpoint')
                length=int(self.headers.get('Content-Length','0'))
                if not 0<length<=10*1024*1024:raise ValueError('Image must be 1 byte to 10 MB')
                raw=self.rfile.read(length)
                with Image.open(io.BytesIO(raw)) as im:
                    if im.width*im.height>20_000_000:raise ValueError('Image too large')
                    im.load()
                    with tempfile.TemporaryDirectory() as td:
                        path=pathlib.Path(td)/'image.png';im.save(path);prob,pred,ms=predict(m,path)
                result={'prediction':pred,'probabilities':{str(name):float(prob[i]) for i,name in enumerate(m['classes'])},'latency_ms':ms,'notice':'Eğitim prototipi; olasılıklar klinik güvenilirlik anlamına gelmez.'};status=200
            except Exception as e:result={'error':str(e)};status=400
            b=json.dumps(result,ensure_ascii=False).encode();self.send_response(status);self.send_header('Content-Type','application/json; charset=utf-8');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b)
    print(f'Open http://127.0.0.1:{a.port}');HTTPServer(('127.0.0.1',a.port),Handler).serve_forever()
if __name__=='__main__':main()
